CREATE FUNCTION touch_updated() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, site text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE skills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, evidence_required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, role_id uuid NOT NULL REFERENCES roles, skill_id uuid NOT NULL REFERENCES skills, minimum_level integer NOT NULL CHECK(minimum_level BETWEEN 1 AND 5), minimum_cover integer NOT NULL DEFAULT 2 CHECK(minimum_cover BETWEEN 1 AND 10000), UNIQUE(role_id,skill_id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, employee_id uuid NOT NULL REFERENCES employees, role_id uuid NOT NULL REFERENCES roles, starts_on date NOT NULL, ends_on date, CHECK(ends_on IS NULL OR ends_on>=starts_on), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, employee_id uuid NOT NULL REFERENCES employees, skill_id uuid NOT NULL REFERENCES skills, level integer NOT NULL CHECK(level BETWEEN 0 AND 5), assessed_on date NOT NULL, expires_on date, assessor text NOT NULL, evidence text NOT NULL DEFAULT '', status text NOT NULL CHECK(status IN ('pending','approved','revoked')), review_note text NOT NULL DEFAULT '', CHECK(expires_on IS NULL OR expires_on>=assessed_on), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE training (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, employee_id uuid NOT NULL REFERENCES employees, skill_id uuid NOT NULL REFERENCES skills, due_on date NOT NULL, owner text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','completed','cancelled')), evidence text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor text NOT NULL, kind text NOT NULL, record_id uuid NOT NULL, operation text NOT NULL, before_record jsonb, after_record jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL, kind text NOT NULL, code text NOT NULL, original jsonb NOT NULL, mapped jsonb NOT NULL, record_id uuid NOT NULL, UNIQUE(source,kind,code), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['employees','roles','skills','requirements','assignments','results','training','audit','import_records'] LOOP EXECUTE format('CREATE TRIGGER touch BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated()',t); EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON %I FROM public',t); END LOOP; END $$;
CREATE VIEW latest_results AS SELECT DISTINCT ON(employee_id,skill_id) * FROM results WHERE assessed_on<=CURRENT_DATE ORDER BY employee_id,skill_id,assessed_on DESC,created_at DESC,id DESC;
CREATE VIEW competency_matrix AS
SELECT e.id employee_id,e.code employee_code,e.name employee,e.site,ro.id role_id,ro.name role,s.id skill_id,s.name skill,q.minimum_level,q.minimum_cover,r.code result_code,r.level,r.status,r.expires_on,
CASE WHEN r.id IS NULL THEN 'missing' WHEN r.status='revoked' THEN 'revoked' WHEN r.status='pending' THEN 'pending' WHEN r.expires_on<CURRENT_DATE THEN 'expired' WHEN r.level<q.minimum_level THEN 'below level' WHEN r.assessor='' OR (s.evidence_required AND r.evidence='') THEN 'missing evidence' ELSE 'current' END readiness
FROM employees e JOIN assignments a ON a.employee_id=e.id AND a.starts_on<=CURRENT_DATE AND (a.ends_on IS NULL OR a.ends_on>=CURRENT_DATE)
JOIN roles ro ON ro.id=a.role_id JOIN requirements q ON q.role_id=ro.id JOIN skills s ON s.id=q.skill_id LEFT JOIN latest_results r ON r.employee_id=e.id AND r.skill_id=s.id WHERE e.active;
CREATE VIEW coverage AS SELECT site,role,skill,minimum_cover,count(DISTINCT employee_id) assigned,count(DISTINCT employee_id) FILTER(WHERE readiness='current') ready,count(DISTINCT employee_id) FILTER(WHERE readiness='current' AND (expires_on IS NULL OR expires_on>=CURRENT_DATE+30)) ready_in_30_days FROM competency_matrix GROUP BY site,role,skill,minimum_cover;
CREATE VIEW training_due AS SELECT t.id,t.code,e.name employee,s.name skill,t.owner,t.due_on,t.status,t.evidence FROM training t JOIN employees e ON e.id=t.employee_id JOIN skills s ON s.id=t.skill_id WHERE e.active AND t.status='open';
CREATE VIEW attention AS SELECT DISTINCT employee_code code,employee,skill,readiness issue FROM competency_matrix WHERE readiness<>'current' UNION ALL SELECT code,employee,skill,'training overdue' FROM training_due WHERE due_on<CURRENT_DATE;
CREATE VIEW compliance_checks AS SELECT employee_code code,employee,skill,'NZ-GRWM-9' rule,readiness finding FROM competency_matrix WHERE readiness<>'current' UNION ALL SELECT r.code,e.name,s.name,'RECORD-EVIDENCE',CASE WHEN r.assessor='' THEN 'assessor missing' ELSE 'evidence missing' END FROM results r JOIN employees e ON e.id=r.employee_id JOIN skills s ON s.id=r.skill_id WHERE r.status='approved' AND (r.assessor='' OR (s.evidence_required AND r.evidence=''));
REVOKE ALL ON latest_results,competency_matrix,coverage,training_due,attention,compliance_checks FROM public;
